const items = $input.all();

return items.map(item => {
  const d = item.json.body || item.json;
  const order = d.order || {};
  const customerName = order.customerName || order.fullName || 'Valued Customer';
  const customerPhone = order.phone || d.phone || '';
  const customerEmail = order.email || d.email || '';
  const orderNumber = order.orderNumber || order.id || 'CVN-' + Date.now().toString(36).toUpperCase();
  const totalAmount = order.totalAmount || order.total || '0';
  const itemsList = Array.isArray(order.items) ? order.items : [];

  const itemsSummary = itemsList.map(it => `• ${it.name || 'Lipstick'} (${it.shade || 'Shade'}) x${it.quantity || 1}`).join('\n');

  // WhatsApp Message for Customer
  const whatsappMessage = 
`✨ *THANK YOU FOR YOUR ORDER!* ✨\n\n` +
`Hello ${customerName},\n` +
`Aapka Cevonne order successfully confirm ho gaya hai! 💄\n\n` +
`📋 *Order ID:* ${orderNumber}\n` +
`💰 *Total Amount:* ₹${totalAmount}\n\n` +
`*Items:*\n${itemsSummary}\n\n` +
`Hamari team aapke shades ko carefully pack kar rahi hai. Jaise hi dispatch hoga, hum tracking link share karenge! 🚀\n\n` +
`Need help? Reply to this message anytime!\n` +
`_Team Cevonne Beauty_`;

  // Email HTML for Customer
  const emailHtml = `
    <div style="font-family: Arial, sans-serif; max-width: 600px; margin: auto; background-color: #0b0b0b; color: #fff; border-radius: 12px; overflow: hidden;">
      <div style="background: linear-gradient(135deg, #111, #e11d48); padding: 30px 20px; text-align: center;">
        <h1 style="margin: 0; font-size: 24px; letter-spacing: 2px;">CEVONNE</h1>
        <p style="margin: 6px 0 0; font-size: 14px; opacity: 0.9;">Order Confirmation - ${orderNumber}</p>
      </div>
      <div style="padding: 24px;">
        <p style="font-size: 16px;">Hi <strong>${customerName}</strong>,</p>
        <p style="color: #ccc; line-height: 1.6;">Thank you for choosing Cevonne! We have received your order and our beauty studio is preparing your premium lipstick items.</p>
        <div style="background-color: #1a1a1a; padding: 16px; border-radius: 8px; margin: 20px 0;">
          <h3 style="margin-top: 0; color: #fda4af; font-size: 16px;">Order Details</h3>
          <p style="margin: 4px 0;"><strong>Order Number:</strong> ${orderNumber}</p>
          <p style="margin: 4px 0;"><strong>Total Paid:</strong> ₹${totalAmount}</p>
        </div>
        <p style="font-size: 13px; color: #888; text-align: center;">If you have any questions, simply reply to this email.</p>
      </div>
    </div>
  `;

  return {
    json: {
      ...d,
      customer_phone: customerPhone.replace(/[^0-9]/g, ''),
      customer_email: customerEmail,
      customer_name: customerName,
      whatsapp_message: whatsappMessage,
      email_subject: `Order Confirmed: ${orderNumber} - Thank you for shopping with Cevonne! ✨`,
      email_html: emailHtml
    }
  };
});

const cart = $('Wait 30 Minutes').first().json;
const d = cart.body || cart;
const customerName = d.customerName || d.fullName || 'there';
const customerPhone = d.phone || '';
const customerEmail = d.email || '';
const checkoutUrl = 'https://cevonne.vercel.app/cart';

const whatsappMessage = 
`💄 *Aapka shade cart me wait kar raha hai!* ✨\n\n` +
`Hey ${customerName},\n` +
`Aapne Cevonne cart me lipstick select ki thi par checkout complete nahi kiya.\n\n` +
`Aapke cart par humne *FREE SHIPPING* unlock kar di hai! 🎁\n\n` +
`Abhi apna order complete karein:\n` +
`👉 ${checkoutUrl}\n\n` +
`_Limited stock available._`;

const emailHtml = `
  <div style="font-family: Arial, sans-serif; max-width: 600px; margin: auto; background-color: #0b0b0b; color: #fff; border-radius: 12px; overflow: hidden;">
    <div style="background: linear-gradient(135deg, #be123c, #fb7185); padding: 30px 20px; text-align: center;">
      <h2 style="margin: 0; color: #fff;">Did you forget something gorgeous? 💋</h2>
    </div>
    <div style="padding: 24px;">
      <p>Hey <strong>${customerName}</strong>,</p>
      <p style="color: #ccc; line-height: 1.6;">Your favorite Cevonne shade is reserved in your cart, but stock is running out fast.</p>
      <div style="text-align: center; margin: 30px 0;">
        <a href="${checkoutUrl}" style="background-color: #e11d48; color: #fff; padding: 14px 28px; text-decoration: none; border-radius: 9999px; font-weight: bold;">Complete My Order &rarr;</a>
      </div>
    </div>
  </div>
`;

return [{
  json: {
    ...d,
    customer_phone: customerPhone.replace(/[^0-9]/g, ''),
    customer_email: customerEmail,
    whatsapp_message: whatsappMessage,
    email_subject: "Your Cevonne cart is waiting (Free Shipping Unlocked! 💄)",
    email_html: emailHtml
  }
}];

// Cart recovery suppressed safely because customer placed an order or opted out
const checkResult = $input.first().json;
const cart = $('Wait 30 Minutes').first().json;
const d = cart.body || cart;

return [{
  json: {
    status: 'SUPPRESSED',
    reason: checkResult.reason || 'PURCHASE_COMPLETED',
    customer: d.customerName || d.email || d.phone,
    orderNumber: checkResult.orderNumber || null,
    message: 'Recovery message suppressed. Customer will NOT be spammed.'
  }
}];
